      "body": "带有隐私关键词的遭遇卡或弱点具有一项显现能力，会秘密地将该卡加入你的手牌。执行此操作时，不应向其他调查员展示该卡或其文本。\n\n• 当一张隐私诡计在你的手牌中时，将它视为位于你的威胁区。其持续能力处于生效状态，其上的能力可以被触发，但只能由你触发。\n\n• 当一名隐私敌人在你的手牌中时，它不被视为与你交战，也不被视为位于你的威胁区；除非另有说明，否则它不会攻击。不过，其持续能力处于生效状态，其上的能力可以被触发，但只能由你触发。\n\n• 一张隐私卡会计入你的手牌上限，但除非卡牌上另有说明，否则不能以任何方式将其从你的手牌中弃掉。当隐私卡被弃掉时，将它放入其对应的弃牌堆。"
