            "流浪者之梦：你端详自己的牌，暗暗藏住笑意。方块 J、黑桃 Q，正好凑成一手无可超越的顺子。你的筹码每局都在变多，这一局也不会例外。赌注你来我往，直到桌边只剩你和对面那个穿白西装的男人。「你确定要这样？」他一边把玩手指一边挑衅。你把所有筹码推进桌心，亮出你的 K 高顺子。「真可惜。」他啧啧出声，亮出一对 2。「看来你把一切都输光了。」你出言抗议，指着自己更大的牌型，可当你再看那手牌时，它已经变了。人头牌上的图案如今是没有眼睛、生着许多张嘴和触手手臂的怪物形状。「9♥-10♣-D♦-C♠-N（自动失败）」牌上这样写着。你惊得张口结舌，被人从牌桌旁架起，推出了门外。"
