          "body": "如果没有达成结局，且至少有一名调查员撤退：\n\n恐慌攫住了你的心神，你从圣玛丽医院的正门冲了出去，尽可能拉开自己与这场该死的蛛群滋生之间的距离。一到家，你就筋疲力尽地瘫倒了。\n\n第二天，你醒来后翻看晨报，指望能看到圣玛丽医院陷入混乱、蛛形纲生物大肆滋生的报道。然而，关于医院的消息一个字也没有。是昨夜的事件发生得太晚，以至于《阿卡姆广告报》来不及报道吗？难道那一切都只是一场噩梦？你穿上外套，回到医院，想要确认昨夜所见是否真实。\n\n当你来到圣玛丽医院时，你以为会看到这栋建筑——或者整个上城区——都被蛛网覆盖。但出乎你意料的是，这里干净得无可挑剔。病人、护士和医生在医院走廊里穿行，仿佛昨夜的一切从未发生。然而，就在你去找你沉睡的同伴之前，一个金发、眼袋沉重的男人朝你走来，把手搭在你的肩上。\n\n「早上好。我们得谈谈。」\n\n• 对游戏结束时每个寄生的地点，在你的战役日志中，在「桥梁进度」旁记录 1 个计数标记。\n\n• 在你的战役日志中记录「马斯沃伦医生生死未卜」。\n\n• 在你的战役日志中记录「伦道夫自己逃出了医院」。任意一名调查员可以选择将伦道夫·卡特（现世囚困）（《食梦者》第 79 号卡）加入其牌库。此卡不计入该调查员的牌库张数。\n\n• 跳过，直接前往〈结局 5〉。"
