          "body": "开场 1：为了阻止梦境与清醒世界之间的融合，你决定以肉身强行闯入「幻梦境」——你那位新同伴伦道夫如此称呼这个维度——而不是在睡梦中前往彼处。「这种方式危险重重，但我认为它胜过另一种选择，」伦道夫声称。「如果我们睡着时前往那里，就可能像你的同伴一样被困住，再也无法醒来。」你表示同意：被困在另一侧，你什么也做不了，尤其是你还想帮助那些正在做梦的同伴。\n\n「我们的第一步是找到一把钥匙。即便在幻梦境与清醒世界接壤的地方，人也不能就这么走过去。我曾经拥有一把通往梦境之门的钥匙，但多年前把它弄丢了，此后再也没能找到，」他哀叹道。\n\n查看战役日志。\n\n• 如果黑猫在你身边，前往〈开场 2〉。\n\n• 否则，跳过，直接前往〈开场 3〉。"
