          "body": "开场 4：你问他，究竟是什么让他的心思从奇幻之物转向了更实际的考虑。他思索了片刻，反复掂量着各种可能。接着，他瞪大了眼睛，意识到了一件重要的事。「很多年前出过一件事。那是我最后一次牵扯进超自然的东西——我是说，在今天之前，」他解释道。「我在商人区那栋废弃老宅旁的墓地里，遇见了我的一个朋友——乔尔·曼顿。就是他们称作不可名状之物的那栋宅子。我不想相信那里真如传说所言闹鬼，可我仅仅是复述了那个传说，就招来了那东西的怒火。」你问起那东西，伦道夫闭上眼睛，一阵剧烈的战栗沿着脊背窜上来。「它无法被描述。我只知道我们勉强活了下来。乔尔受伤是我的错。从那天起，我就再也不愿深究超自然或迷信之事。不是因为我信，而是因为我害怕。这就是钥匙躲着我的原因吗？这就是我再也不能做梦的原因吗？」领悟如白昼般击中了他。「我知道我们该去哪儿了。我就是在那里丢了钥匙。那里一定能把它找回来！」他瞪大眼睛喊道。\n\n伦道夫手忙脚乱地想要拦一辆出租车，你这才明白他打算去哪儿：去那栋无名之屋，去那个至今仍在他记忆中作祟、难以描述的怪物所在之处……"
