            "body": "这里与维吉尔·格雷在故事中写到的神秘森林、迷人的中世纪村庄和壮丽全景截然不同。不，恰恰相反：这片寒冷荒凉的深渊正一点点吞噬你的希望，代之以空洞而无意义的恐惧。你问伦道夫，这里是不是通往你那几位昏迷同伴的路。你几乎希望自己走错了方向，好把这可怕的地方抛在身后。\n\n「我不知道，」他答道，一边从楼梯旁的窗户向外张望。「我们已经越过了清醒世界，但这里是幻梦境的低层界域，被称为地下世界。那是个不宜久留的地方。我们见过的许多越界进入我们世界的生物，都来自这片区域。也许我们的钥匙早就知道，这里才是我们真正的目的地？」你的向导端详着你在那栋废弃宅子里找到的秘术钥匙，手指抚过它上面的阿拉伯式花纹，仿佛在回忆它的形状、重量与质地。他因失去之深而眼眶湿润。\n\n你主动提出替他拿着钥匙，这把他从独自的思绪中拉了回来。「啊。对，也许这样最好，」他说着，把这件精致的器物交到你手上。对一件据伦道夫说并不真实的东西来说，它重得出奇。\n\n带着伦道夫和银钥匙，你重新踏上向下的路。你的同伴也许在地下世界，也许不在，但如果那些入侵清醒世界的生物确实来自这里，那么也许你能在此找到答案。\n\n• 在你的战役日志中记录「伦道夫安全下降到地下世界」。\n\n• 在你的战役日志中记录「调查员持有银钥匙」。任意一名调查员可以选择将银钥匙（梦境之门的钥匙）加入自己的牌库。此卡不计入该调查员的牌库张数。\n\n• 每名调查员获得经验，数值等于胜利区中每张卡牌的胜利 X 值。\n\n• 你的肉身如今行走在沉睡的幻梦境之中。在战役余下的时间里，向混乱袋添加 1 个 [skull] 标记。\n\n• 如果你以四章战役的形式进行梦网，前往〈剧本 3–B：无归之地〉。\n\n• 如果你以互联的八章战役形式同时进行梦寻与梦网……\n\n• ……且尚未进行〈剧本 2–A：寻觅卡达斯〉，前往该剧本。\n\n• ……且已经进行过〈剧本 2–A：寻觅卡达斯〉，改为前往〈幕间 II：入梦者〉。"
