          "setEncounterSetsAside": "将以下每个遭遇组放在一边，置于游戏外：深入漆黑、山谷恐怖、阿特拉克·纳克亚的使徒，以及夜魇。这些遭遇组由以下图标标示：",
          "putLocations": "将以下地点放入游戏：辛之墓穴、古革巨人之城、卡斯之塔，以及食尸鬼平原。",
          "beginAtVaultsOfZin": "每名调查员从辛之墓穴开始游戏。",
          "setOtherLocationsAside": "将其他每个地点放在一边，置于游戏外。",
          "setEnchantedWoodsAside": "在卡牌收藏中搜寻魔幻森林（石板暗门）（《食梦者》第 53 号卡），将其放在一边，置于游戏外。",
          "setCardsAside": "将古革哨兵敌人、理查德·厄普顿·皮克曼剧情支援，以及假醒弱点放在一边，置于游戏外。",
          "checkAct": "查看战役日志。根据以下情况，本剧本应使用不同版本的幕 1。将另一个版本的幕 1 从游戏中移除。",
          "useActV1": "如果伦道夫在下降到地下世界的途中遇难，使用幕 1a——“进入地下世界（版本一）”。",
          "useActV2": "如果伦道夫安全下降到地下世界，使用幕 1a——“进入地下世界（版本二）”。",
          "checkSteps": "一阵疼痛与恶心席卷全身。查看战役日志中「桥梁进度」旁记录的计数标记数量。",
