          "oneToFourSteps": "如果有 1–4 个计数标记，在剧本参考卡上放置 1 点伤害。这代表幻梦境内部的扭曲。",
          "fiveOrMoreSteps": "如果有 5 个或更多计数标记，在剧本参考卡上放置 2 点伤害。这代表幻梦境内部的扭曲。",
