            "body": "本剧本中的每个地点都没有未揭示的一面，因此它们以已揭示的一面朝上进入游戏。这些地点的背面放的并非未揭示的一面，而是剧情卡。每当本剧本中的一个地点进入游戏时（包括在设置期间），照常在该地点上放置等于其线索值的线索。\n\n地点可以通过以下两种方式之一翻面。大多数地点由下文所述的「掩藏」关键词翻面。有些地点则改为通过印在该地点上的能力翻面。\n\n一旦某个地点翻面，且其剧情文字已被阅读，除非另有说明，否则在游戏余下的时间里它不能再次翻面。"
