          "body": "宏大计划 2：你转向伦道夫，想从他那里得到答案。这一路的疯狂，全靠他为你引路。他一定知道这是怎么回事。「终于，」他睁大双眼凝望着大厅，说道，「我们抵达了伟大的存在的殿堂——凡人不得直视的存在。我们明知这是禁忌，可我们还是来了，我们的征程完成了。」他转向维吉尔。「这一切值得吗，先生？你找到你要的证据了吗？」\n\n维吉尔后退了一步。「你在说什么，伦道夫？这难道不是你的主意吗？从一开始，就是你把我们带上这趟征程的。」\n\n伦道夫微笑着，把一只手搭在维吉尔的肩上。「没错，是我。但我不是伦道夫·卡特。」他抽回另一条手臂，还没等你反应过来，就将一柄锋如剃刀的缟玛瑙短刃刺进了维吉尔·格雷的胸膛。维吉尔的尸体滑落在打磨光滑的地面上，双眼永远凝固在悲怆的惊骇之中。那个从来就不是伦道夫·卡特的存在转向你，它的影子在地面上拉长，化作多重形状。「看哪！」它用许多个声音低吼道，「你应得的奖赏！」\n\n• 如果某名调查员的牌组中包含伦道夫·卡特（梦境专家）（《食梦者》第 59 号卡），在战役余下的时间里，把他从该牌组中移除。\n\n• 查看战役日志。\n\n• 如果黑猫在你身边，跳过，直接前往〈宏大计划 4〉。\n\n• 否则，跳过，直接前往〈宏大计划 5〉。"
