          "body": "你阻止了蜘蛛神完成它的蛛网，但在此过程中，你也切断了自己返回家乡最快的路。于是，任务完成后，你开始了朝向现实的漫长攀登。幸好蛛网之桥仍有残迹完好留存，否则你就会被困在这地狱般的诸世界之间。你花了许多个小时才循原路返回地下世界。你最终从浓稠如焦油的漆黑之海中浮出，靠近海岸。令你沮丧的是，你意识到自己身处大海对岸，而你当初启程的那片黑暗山谷在另一侧。由于无法渡过这片致命的海，你只能另寻离开这片荒芜之地的办法。数天过去，你继续探索地下世界，随着你在地球幻梦境的地壳之下越走越深，你所到之处也愈发黑暗、愈发禁忌。虽然你最终找到了一道向上的阶梯，但它与通往不可名状之物的那道阶梯截然不同：一连串螺旋上升、异界般的台阶，通向令人目眩的高度，打破了现实的一切法则。当你到达顶端时，你的心沉了下去。这里丝毫没有阿卡姆的迹象。迎接你的是一座陌生而破败的城市，以及城中半人半兽的居民。这些生物告诉你，你已抵达失落的城市「萨克曼德」。看来你的归途还远未结束。\n\n• 在你的战役日志中记录「调查员仍在幻梦境」。\n\n• 每名调查员因与蜘蛛神的激战而承受 2 点肉体创伤。\n\n• 如果你正以四章战役的形式进行《梦网》，调查员赢得了这场战役！\n\n• 如果你正以互联的八章战役的形式进行《梦寻》与《梦网》……\n\n• ……并且你尚未进行过〈剧本 4–A：神居之所〉，前往该剧本。\n\n• ……并且你已经进行过〈剧本 4–A：神居之所〉，改为前往〈尾声〉。"
