          "body": "蜘蛛女王 1：你攀上一处石崖，望见蜘蛛之桥的庞然巨构，以及跨踞其上的那东西：蜘蛛之神阿特拉克·纳克亚，伴随它的是成群的织网者。那些多足的怪物不断交织宇宙蛛网，以噩梦般的狂热无休无止地劳作。随着这些可怖的生物织出一根根丝线，你感到现实与梦境扭曲、碰撞、彼此冲击。在远处，梦的浪潮拍打在现实的礁石上，现实则自行坍缩进翻涌不定、无形无状的梦境之中。你几乎无法理解那些奇异变幻的景象。一挂黏稠的蛛网从你所立之处的一侧垂下，宛如一架通往你末日的丝梯。\n\n• 查看战役日志。\n\n• 如果伦道夫安全下降到地下世界，且黑猫得知真相，前往〈蜘蛛女王 2〉。\n\n• 否则，如果伦道夫安全下降到地下世界，跳过，直接前往〈蜘蛛女王 3〉。\n\n• 如果伦道夫在下降到地下世界的途中遇难，跳过，直接前往〈蜘蛛女王 4〉。"
