          "body": "蜘蛛女王 2：你正要顺着蛛网爬向下方的平台，忽然听见黑猫的声音从你的同伴伦道夫身后传来。「扔掉它，」那声音命令道。一丝阴险的笑容在伦道夫脸上绽开，他丢下一柄锯齿状的缟玛瑙短刀，刀身哐当一声落在地上。\n\n「这么说，你已经看穿了我的面具？」他说。「没关系。无论如何，你都会完成我派给你的这桩差事。你的世界全靠它了。」\n\n你满心困惑，问伦道夫为何会变成这样。黑猫跳上你的肩头，栖在那里，目光始终没有离开你那位从前的同伴。「我前不久才弄明白。他不是伦道夫。他从来都不是。只是一个披着伦道夫皮囊的闯入者。」\n\n「闯入者？」伦道夫怒吼道。「你，猫，才是闯入者！没错，我知道你是什么。这里不是你的地方。但话已说得够多了。」一抹笑意再次爬上他的嘴唇。「你还有任务要完成。那么，再会了……暂时。」警告完毕，假伦道夫便走出平台边缘，坠入虚无之中。\n\n• 如果某名调查员的牌库中包含伦道夫·卡特（现世囚困）（《食梦者》第 79 号卡），则在战役余下的时间里，将他从该牌库中移除。\n\n• 跳过，直接前往〈蜘蛛女王 4〉。"
