    "theDreamEaters.label.blackCatWandersOff": "你还没来得及回答，黑猫便走开了，它乌黑的皮毛融入了地下世界的黑暗之中。",
    "theDreamEaters.label.youDidNotAskForItRequestAid": "告诉同伴你们陷入了困境。这条口信送到之后，黑猫会带着援助回到你们身边。这可能会给你的同伴增添过重的负担。",
    "theDreamEaters.label.youDidNotAskForItKnowledgeOfUnderworld": "告诉同伴关于地下世界的事情。之后黑猫会去别处。",
