    "theDreamEaters.label.blackCatBoundsOff": "你还没来得及再问它什么，黑猫就一跃跳进了太空的虚空之中。",
    "theDreamEaters.label.theGreatOnes1SpokeOfNyarlathotep": "告诉同伴你们面对的那些威胁。这条口信送到之后，黑猫会带着援助回到你们身边。这可能会给你的同伴增添过重的负担。",
    "theDreamEaters.label.theGreatOnes1SpokeOfAtlachNacha": "告诉同伴你们会没事的。这条口信送到之后，黑猫会留在他们身边。这可能会让你的追寻稍微困难一些。",
